def terminal_packet(moment, endpoint, order):
    """Evaluate T(moment, endpoint, order) coefficient by coefficient."""

    return ZZ(
        sum(
            (-_sage_const_1 ) ** residue
            * binomial(order, residue)
            * coefficient(
                moment,
                (endpoint - residue) * kappa[_sage_const_0 ],
                (endpoint - residue) * kappa[_sage_const_1 ],
                (endpoint - residue) * kappa[_sage_const_2 ],
            )
            for kappa in polytope_points(_sage_const_1 )
            for residue in range(order + _sage_const_1 )
        )
    )


def direct_difference(moment, endpoint, order):
    start = endpoint - order
    values = shell_batch(moment, range(start, endpoint + _sage_const_1 ))
    return ZZ(
        sum(
            (-_sage_const_1 ) ** residue
            * binomial(order, residue)
            * values[endpoint - residue]
            for residue in range(order + _sage_const_1 )
        )
    )


def terminal_origin_coordinate(global_index, endpoint, order):
    """The compact terminal-packet formula for Delta^L W."""

    moment = global_index - _sage_const_1 
    return ZZ(
        sum(
            ZZ(integer_coefficients[shift](n=global_index))
            * (
                terminal_packet(
                    global_index + shift, endpoint - _sage_const_1 , order
                )
                + terminal_packet(
                    global_index + shift, endpoint + _sage_const_1 , order
                )
            )
            for shift in range(origin_operator.order() + _sage_const_1 )
        )
        - ZZ(multiplier(n=global_index))
        * terminal_packet(moment, endpoint, order)
    )


def direct_origin_coordinate(global_index, endpoint, order):
    moment = global_index - _sage_const_1 
    start = endpoint - order
    nodes = list(range(start, endpoint + _sage_const_1 ))
    required = list(range(start - _sage_const_1 , endpoint + _sage_const_2 ))
    old = shell_batch(moment, nodes)
    shifted = {
        shift: shell_batch(global_index + shift, required)
        for shift in range(origin_operator.order() + _sage_const_1 )
    }
    values = {
        node: sum(
            ZZ(integer_coefficients[shift](n=global_index))
            * (
                shifted[shift][node - _sage_const_1 ]
                + shifted[shift][node + _sage_const_1 ]
            )
            for shift in range(origin_operator.order() + _sage_const_1 )
        )
        - ZZ(multiplier(n=global_index)) * old[node]
        for node in nodes
    }
    return ZZ(
        sum(
            (-_sage_const_1 ) ** residue
            * binomial(order, residue)
            * values[endpoint - residue]
            for residue in range(order + _sage_const_1 )
        )
    )


