def terminal_yw_table(moment, maximum_order):
    """Return the exact terminal high-difference vectors (B_Y,B_W)."""

    global_index = moment + _sage_const_1 
    nodes = list(range(moment - maximum_order, moment + _sage_const_1 ))
    required = list(range(nodes[_sage_const_0 ] - _sage_const_1 , nodes[-_sage_const_1 ] + _sage_const_2 ))
    old = shell_batch(moment, nodes)
    shifted = {
        shift: shell_batch(global_index + shift, required)
        for shift in range(origin_operator.order() + _sage_const_1 )
    }
    mu = ZZ(multiplier(n=global_index))
    w_values = {
        node: sum(
            ZZ(integer_coefficients[shift](n=global_index))
            * (
                shifted[shift][node - _sage_const_1 ]
                + shifted[shift][node + _sage_const_1 ]
            )
            for shift in range(origin_operator.order() + _sage_const_1 )
        )
        - mu * old[node]
        for node in nodes
    }
    return (
        terminal_difference_table(old),
        terminal_difference_table(w_values),
    )


def audit_terminal_wedges():
    """Measure exact adjacent wedges after primitive vector saturation."""

    for moment in (_sage_const_20 , _sage_const_30 , _sage_const_40 , _sage_const_50 , _sage_const_60 , _sage_const_80 ):
        maximum_order = (moment - _sage_const_8 ) // _sage_const_2 
        by, bw = terminal_yw_table(moment, maximum_order)
        primitive_vectors = []
        for order in range(_sage_const_1 , maximum_order + _sage_const_1 ):
            content = gcd(by[order], bw[order])
            primitive_vectors.append(
                (
                    by[order] // content,
                    bw[order] // content,
                )
            )
        wedges = [
            left[_sage_const_0 ] * right[_sage_const_1 ] - left[_sage_const_1 ] * right[_sage_const_0 ]
            for left, right in zip(
                primitive_vectors, primitive_vectors[_sage_const_1 :]
            )
        ]
        last = wedges[-_sage_const_1 ]
        all_wedge_gcd = gcd(wedges)
        component_bits = max(
            abs(entry).nbits()
            for vector in primitive_vectors[-_sage_const_2 :]
            for entry in vector
        )
        print(
            "TERMINAL_WEDGE",
            "M",
            moment,
            "L",
            maximum_order - _sage_const_1 ,
            "component_bits",
            component_bits,
            "last_wedge_bits",
            abs(last).nbits(),
            "all_wedge_gcd_bits",
            abs(all_wedge_gcd).nbits(),
            "all_wedge_gcd",
            all_wedge_gcd,
        )


if "--wedge-height" in sys.argv:
    audit_terminal_wedges()


def audit_terminal_exterior_sequence():
    """Measure the diagonal once-divided Y/W exterior sequence.

    If ``V_L=(f_L(Y),f_L(W))`` and

        V_L-V_{L-1}=(-1)^L binom(M+1,L) B_L,

    then the adjacent Newton determinant divided by its universal
    Pascal factor is ``det(B_L,V_{L-1})``.  This is the terminal
    specialization of the normalized exterior carrier.
    """

    for moment in (_sage_const_20 , _sage_const_30 , _sage_const_40 , _sage_const_50 , _sage_const_60 , _sage_const_80 , _sage_const_100 ):
        maximum_order = (moment - _sage_const_8 ) // _sage_const_2 
        by, bw = terminal_yw_table(moment, maximum_order)
        fy = [terminal_packet(moment, moment, _sage_const_0 )]
        fw = [
            terminal_origin_coordinate(
                moment + _sage_const_1 , moment, _sage_const_0 
            )
        ]
        for order in range(_sage_const_1 , maximum_order + _sage_const_1 ):
            pascal = (-_sage_const_1 ) ** order * binomial(
                moment + _sage_const_1 , order
            )
            fy.append(fy[-_sage_const_1 ] + pascal * by[order])
            fw.append(fw[-_sage_const_1 ] + pascal * bw[order])
        exterior = [
            by[order] * fw[order - _sage_const_1 ]
            - bw[order] * fy[order - _sage_const_1 ]
            for order in range(_sage_const_1 , maximum_order + _sage_const_1 )
        ]
        exterior_gcd = gcd(exterior)
        prefix_gcds = []
        running_gcd = ZZ.zero()
        for value in exterior[:_sage_const_10 ]:
            running_gcd = gcd(running_gcd, value)
            prefix_gcds.append(abs(running_gcd).nbits())
        operator_content = gcd(
            [
                ZZ(multiplier(n=moment + _sage_const_1 )),
                *[
                    ZZ(
                        integer_coefficients[shift](
                            n=moment + _sage_const_1 
                        )
                    )
                    for shift in range(
                        origin_operator.order() + _sage_const_1 
                    )
                ],
            ]
        )
        print(
            "TERMINAL_EXTERIOR",
            "M",
            moment,
            "Lmax",
            maximum_order,
            "gcd_bits",
            abs(exterior_gcd).nbits(),
            "gcd",
            factor(exterior_gcd),
            "operator_content",
            factor(operator_content),
            "quotient",
            factor(exterior_gcd // gcd(
                exterior_gcd, operator_content
            )),
            "first_bits",
            [abs(value).nbits() for value in exterior[:_sage_const_5 ]],
            "prefix_gcd_bits",
            prefix_gcds,
        )


if "--terminal-exterior" in sys.argv:
    audit_terminal_exterior_sequence()


def audit_hostile_terminal_exterior_prefix():
    """Check the first seven exterior values at hostile target indices."""

    for moment in (_sage_const_199 , _sage_const_271 , _sage_const_299 , _sage_const_320 ):
        maximum_order = _sage_const_7 
        by, bw = terminal_yw_table(moment, maximum_order)
        fy = [terminal_packet(moment, moment, _sage_const_0 )]
        fw = [
            terminal_origin_coordinate(
                moment + _sage_const_1 , moment, _sage_const_0 
            )
        ]
        exterior = []
        for order in range(_sage_const_1 , maximum_order + _sage_const_1 ):
            exterior.append(
                by[order] * fw[-_sage_const_1 ]
                - bw[order] * fy[-_sage_const_1 ]
            )
            pascal = (-_sage_const_1 ) ** order * binomial(
                moment + _sage_const_1 , order
            )
            fy.append(fy[-_sage_const_1 ] + pascal * by[order])
            fw.append(fw[-_sage_const_1 ] + pascal * bw[order])
        exterior_gcd = gcd(exterior)
        print(
            "HOSTILE_TERMINAL_EXTERIOR_PREFIX",
            "M",
            moment,
            "gcd_bits",
            abs(exterior_gcd).nbits(),
            "gcd_factorization",
            factor(exterior_gcd),
        )


if "--hostile-terminal-exterior" in sys.argv:
    audit_hostile_terminal_exterior_prefix()


def terminal_yw_table_mod(moment, maximum_order, modulus):
    """Return terminal Y/W differences modulo ``modulus``."""

    global_index = moment + _sage_const_1 
    nodes = list(range(moment - maximum_order, moment + _sage_const_1 ))
    required = list(range(nodes[_sage_const_0 ] - _sage_const_1 , nodes[-_sage_const_1 ] + _sage_const_2 ))
    old = shell_batch(moment, nodes, modulus=modulus)
    shifted = {
        shift: shell_batch(
            global_index + shift,
            required,
            modulus=modulus,
        )
        for shift in range(origin_operator.order() + _sage_const_1 )
    }
    mu = ZZ(multiplier(n=global_index)) % modulus
    w_values = {
        node: (
            sum(
                (
                    ZZ(
                        integer_coefficients[shift](
                            n=global_index
                        )
                    )
                    % modulus
                )
                * (
                    shifted[shift][node - _sage_const_1 ]
                    + shifted[shift][node + _sage_const_1 ]
                )
                for shift in range(
                    origin_operator.order() + _sage_const_1 
                )
            )
            - mu * old[node]
        )
        % modulus
        for node in nodes
    }
    return (
        [
            value % modulus
            for value in terminal_difference_table(old)
        ],
        [
            value % modulus
            for value in terminal_difference_table(w_values)
        ],
        old[moment] % modulus,
        w_values[moment] % modulus,
    )


def audit_target_boundary_jets():
    """Print the first divided terminal exterior digit at exact targets."""

    targets = (
        (_sage_const_199 , _sage_const_139 ),
        (_sage_const_199 , _sage_const_181 ),
        (_sage_const_271 , _sage_const_191 ),
        (_sage_const_271 , _sage_const_233 ),
        (_sage_const_299 , _sage_const_191 ),
        (_sage_const_299 , _sage_const_227 ),
        (_sage_const_320 , _sage_const_179 ),
        (_sage_const_320 , _sage_const_193 ),
        (_sage_const_320 , _sage_const_211 ),
    )
    for moment, prime in targets:
        global_index = moment + _sage_const_1 
        residue = global_index - prime
        modulus = prime**_sage_const_2 
        by, bw, fy, fw = terminal_yw_table_mod(
            moment, residue, modulus
        )
        for order in range(_sage_const_1 , residue + _sage_const_1 ):
            pascal = (
                (-_sage_const_1 ) ** order
                * binomial(moment + _sage_const_1 , order)
            ) % modulus
            previous_y, previous_w = fy, fw
            fy = (fy + pascal * by[order]) % modulus
            fw = (fw + pascal * bw[order]) % modulus
        exterior = (
            by[residue] * previous_w
            - bw[residue] * previous_y
        ) % modulus
        assert fy % prime == _sage_const_0 
        assert fw % prime == _sage_const_0 
        assert exterior % prime == _sage_const_0 
        print(
            "TARGET_BOUNDARY_JET",
            "M",
            moment,
            "p",
            prime,
            "r",
            residue,
            "Y_div",
            (fy // prime) % prime,
            "W_div",
            (fw // prime) % prime,
            "E_div",
            (exterior // prime) % prime,
            "B",
            (by[residue] % prime, bw[residue] % prime),
        )


if "--target-boundary-jets" in sys.argv:
    audit_target_boundary_jets()


RAY_CLASSES = (
    ((-_sage_const_1 , -_sage_const_1 , -_sage_const_1 ), _sage_const_1 ),
    ((-_sage_const_1 , -_sage_const_1 , _sage_const_0 ), _sage_const_2 ),
    ((-_sage_const_1 , -_sage_const_1 , _sage_const_1 ), _sage_const_2 ),
    ((-_sage_const_1 , _sage_const_0 , _sage_const_0 ), _sage_const_1 ),
    ((-_sage_const_1 , _sage_const_0 , _sage_const_1 ), _sage_const_2 ),
    ((-_sage_const_1 , _sage_const_1 , _sage_const_1 ), _sage_const_1 ),
    ((_sage_const_0 , -_sage_const_1 , -_sage_const_1 ), _sage_const_1 ),
    ((_sage_const_0 , -_sage_const_1 , _sage_const_0 ), _sage_const_2 ),
    ((_sage_const_0 , -_sage_const_1 , _sage_const_1 ), _sage_const_2 ),
    ((_sage_const_0 , _sage_const_0 , _sage_const_1 ), _sage_const_2 ),
    ((_sage_const_0 , _sage_const_1 , _sage_const_1 ), _sage_const_1 ),
    ((_sage_const_1 , _sage_const_0 , _sage_const_0 ), _sage_const_1 ),
    ((_sage_const_1 , _sage_const_0 , _sage_const_1 ), _sage_const_2 ),
    ((_sage_const_1 , _sage_const_1 , _sage_const_1 ), _sage_const_1 ),
)


def search_polynomial_ray_syzygies():
    """Look for low-degree relations among the 14 summed-label ray classes."""

    prime = _sage_const_1000000007 
    field = GF(prime)
    data = []
    for moment in range(_sage_const_8 , _sage_const_51 ):
        for residue in range((moment - _sage_const_1 ) // _sage_const_2  + _sage_const_1 ):
            node = moment - residue
            values = [
                (
                    multiplicity
                    * coefficient(
                        moment,
                        node * point[_sage_const_0 ],
                        node * point[_sage_const_1 ],
                        node * point[_sage_const_2 ],
                        modulus=prime,
                    )
                )
                % prime
                for point, multiplicity in RAY_CLASSES
            ]
            data.append((moment, residue, values))
    holdout = _sage_const_80 
    for degree in range(_sage_const_7 ):
        monomial_count = (degree + _sage_const_1 ) * (degree + _sage_const_2 ) // _sage_const_2 
        column_count = len(RAY_CLASSES) * monomial_count
        if len(data) <= column_count + holdout:
            continue
        rows = []
        for moment, residue, values in data[:-holdout]:
            monomials = total_degree_monomials(
                field, moment, residue, degree
            )
            rows.append(
                [
                    value * monomial
                    for value in values
                    for monomial in monomials
                ]
            )
        kernel = matrix(field, rows).right_kernel()
        valid_dimension = _sage_const_0 
        for candidate in kernel.basis():
            if all(
                sum(
                    candidate[
                        block * monomial_count + column
                    ]
                    * value
                    * monomial
                    for block, value in enumerate(values)
                    for column, monomial in enumerate(
                        total_degree_monomials(
                            field, moment, residue, degree
                        )
                    )
                )
                == _sage_const_0 
                for moment, residue, values in data[-holdout:]
            ):
                valid_dimension += _sage_const_1 
        print(
            "RAY_SYZYGY_SEARCH",
            "degree",
            degree,
            "columns",
            column_count,
            "training_kernel",
            kernel.dimension(),
            "holdout_valid",
            valid_dimension,
        )


if "--ray-syzygy" in sys.argv:
    search_polynomial_ray_syzygies()

